def find_record(ids, target):
    low, high = 0, len(ids) - 1
    while low <= high:
        mid = (low + high) // 2
        if ids[mid] == target:
            return mid
        if ids[mid] < target:
            low = mid + 1
        else:
            high = mid - 1
    return -1
